source("pre.R")
suppressMessages(library(vctrs))
tw <- id_layout("twitter"); dc <- id_layout("discord")
s1 <- id_parse(c("9","10"), "snowflake", layout=tw)
p("vec_assign diff layout", {y <- s1; vec_slice(y, 1) <- id_parse("7","snowflake",layout=dc); y})
p("coalesce", dplyr::coalesce(c(s1, NA), s1[1]))
p("blocklist effect", {x <- sqids(list(c(1,2,3), c(4,5,6))); bl <- as.character(x)[2]; y <- sqids(list(c(1,2,3), c(4,5,6)), blocklist=toupper(bl)); print(rbind(as.character(x), as.character(y))); print(id_fields(y)$numbers); print(id_valid(as.character(y), "sqids")); print(id_valid(y, "sqids")); id_parse(as.character(y), "sqids")})
p("default blocklist: text made w/ empty blocklist", {y <- sqids(list(c(1,2,3)), blocklist=character()); print(y); id_valid(as.character(y), "sqids")})
x <- nanoid(2, alphabet="ab")
p("nanoid valid", list(id_valid(x, "nanoid"), id_valid(c(as.character(x), "abz"), "nanoid", alphabet="ab"), id_valid(c(as.character(x),"ab z","a\nb", "é"), "nanoid")))
# id_valid / id_parse value matrix
u <- "018f6b1c-2d3e-7a4b-8c5d-6e7f8091a2b3"
p("valid factor", id_valid(factor(u), "uuid")); p("valid num", id_valid(5, "uuid")); p("valid NULL", id_valid(NULL, "uuid")); p("valid logical NA", id_valid(NA, "uuid")); p("valid list", id_valid(list(u), "uuid")); p("valid chr0", id_valid(character(), "uuid"))
p("valid names", id_valid(c(a=u, a="x", NA), "uuid")); p("valid ws/newline", id_valid(c(paste0(u,"\n"), paste0(" ",u), paste0(u," "), paste0(u, "é")), "uuid"))
p("valid latin1", {z <- "018f6b1c-2d3e-7a4b-8c5d-6e7f8091a2b\xe9"; Encoding(z) <- "latin1"; id_valid(z, "uuid")})
p("valid fullwidth digits", id_valid("０１", "snowflake", layout=tw))
p("valid format missing", id_valid(u)); p("format NULL", id_valid(u, NULL)); p("format upper", id_valid(u, "UUID")); p("format factor", id_valid(u, factor("uuid"))); p("format partial", id_valid(u, "uu"))
p("level bad", id_valid(u, "uuid", level="x")); p("level partial", id_valid(u, "uuid", level="str")); p("level vec", id_valid(u, "uuid", level=c("syntax","strict")))
p("strict NA", id_parse(u, "uuid", strict=NA)); p("strict 1", id_parse(u, "uuid", strict=1)); p("strict err", id_parse(c(u,"x",NA), "uuid", strict=TRUE))
p("strict err positions", tryCatch(id_parse(c(u,"x",NA,"y"), "uuid", strict=TRUE), error=function(e) e$positions))
p("parse names", names(id_parse(c(a=u, a=NA), "uuid"))); p("parse zuid other format", id_parse(id_parse(u,"uuid"), "ulid")); p("parse zuid same", identical(id_parse(id_parse(u,"uuid")), id_parse(u,"uuid")))
p("parse zuid w/ form", id_parse(id_parse(u,"uuid"), form="compact"))
p("variants", id_valid(c("018f6b1c-2d3e-7a4b-0c5d-6e7f8091a2b3","018f6b1c-2d3e-9a4b-8c5d-6e7f8091a2b3","018f6b1c-2d3e-0a4b-8c5d-6e7f8091a2b3"), "uuid"))
p("variants strict", id_valid(c("018f6b1c-2d3e-9a4b-8c5d-6e7f8091a2b3","018f6b1c-2d3e-0a4b-8c5d-6e7f8091a2b3","ffffffff-ffff-7fff-bfff-ffffffffffff"), "uuid", level="strict"))
# time tolerance option
fut <- uuid(1, 7, time = Sys.time() + 3600)
p("future default", id_valid(fut, "uuid", level="strict"))
for (o in list(0, -1, NA, "a", c(1,2), NULL, Inf, 1e300, TRUE, 3600L)) { options(zuid.time_tolerance = o); cat("tol =", deparse(o), ": "); t(id_valid(fut, "uuid", level="strict")) }
options(zuid.time_tolerance = NULL)
for (o in list(0, -1, NA, "a", c(1,2), Inf)) { options(zuid.clock_tolerance = o); cat("clock tol =", deparse(o), ": "); t(as.character(snowflake(1, tw, list(worker=1,datacenter=1)))) }
options(zuid.clock_tolerance = NULL)
for (o in list(-1, NA, "a", c(1,2), Inf)) { options(zuid.rollback_tolerance = o); cat("rollback tol =", deparse(o), ": "); t(length(uuid(1))) }
options(zuid.rollback_tolerance = NULL)
p("strict snowflake future", {s <- snowflake(1, tw, list(worker=1,datacenter=1), time=Sys.time()+1e6, rollback="reset"); c(id_valid(s,"snowflake",level="strict"), id_valid(s,"snowflake"))})
p("strict ksuid/xid/ulid future", c(id_valid(ksuid(1,time=Sys.time()+1e6),"ksuid",level="strict"), id_valid(xid(1,time=Sys.time()+1e6),"xid",level="strict"), id_valid(ulid(1,time=Sys.time()+1e6),"ulid",level="strict"), id_valid(objectid(1,time=Sys.time()+1e6),"objectid",level="strict"), id_valid(upid(1,"a",time=Sys.time()+1e6),"upid",level="strict"), id_valid(scru128(1,time=Sys.time()+1e6),"scru128",level="strict"), id_valid(typeid(1,"a",time=Sys.time()+2e6),"typeid",level="strict")))
p("strict scru64 future w/o and w/ layout", {s <- scru64(1,1,8,time=Sys.time()+1e6); c(id_valid(s,"scru64",level="strict"), id_valid(s,"scru64",level="strict",layout=id_layout("scru64",node_bits=8)))})
# detect
p("detect mix", id_detect(c(a=u, b="01ARZ3NDEKTSV4RRFFQ69G5FAV", c="01arz3ndektsv4rrffq69g5fav", d="0un7yrlrmklh", e="9", f=NA)))
p("detect w scru64 layout", id_detect(c("0un7yrlrmklh","9"), layout=id_layout("scru64",node_bits=8)))
p("detect w tw", id_detect(c("0un7yrlrmklh","9", "175928847299117063"), layout=tw))
p("detect hint dup/unknown", id_detect("abc", hint=c("nanoid","nanoid","cuid2"))); p("hint bad", id_detect("abc", hint="nope")); p("hint NA", id_detect("abc", hint=NA)); p("hint empty", id_detect("abc", hint=character()))
p("detect factor", id_detect(factor(u))); p("detect zuid", id_detect(id_parse(u,"uuid"))); p("detect layout bad", id_detect("9", layout=list(name="x")))
p("detect 12 digits (scru64 vs snowflake)", id_detect("123456789012", layout=tw))
p("parse detect snowflake", id_parse("175928847299117063", layout=dc)); p("parse detect scru64", attr(id_parse("0un7yrlrmklh", layout=id_layout("scru64",node_bits=8)), "layout")$name)
p("parse 26 lower ambiguous", id_parse("01arz3ndektsv4rrffq69g5fav")); p("parse mixed", id_parse(c(u, "01ARZ3NDEKTSV4RRFFQ69G5FAV")))
p("parse uuid layout", id_parse(u, "uuid", layout=tw)); p("parse scru64 w/ tw layout", id_parse("0un7yrlrmklh", "scru64", layout=tw))
p("scru64 fields w/o layout", id_fields(scru64(1, 5, 8))[,c("time_unit","node","sequence")]); p("scru64 fields with layout", {s <- scru64(2, 5, 8, random=as.raw(1:6), time=1e12); id_fields(id_parse(s, layout=id_layout("scru64", node_bits=8)))[,c("time","time_unit","node","sequence")]})
p("scru64 node range", scru64(1, 256, 8)); p("scru64 node NA", scru64(1, NA, 8)); p("scru64 nb 24", scru64(1,1,24)); p("scru64 nb 0", scru64(1,0,0)); p("nb vec", scru64(1,1,c(8,9))); p("nb chr", scru64(1,1,"8")); p("node -1", scru64(1,-1,8)); p("node 1.5", scru64(1,1.5,8)); p("nb int", length(scru64(1,1L,8L)))
p("uuid n", list(uuid(0), t(uuid(-1)), t(uuid(1.5)), t(uuid(NA)), t(uuid(c(1,2))), t(uuid("1")), t(uuid(TRUE)), t(uuid(2^31)), t(uuid(Inf)), length(uuid(2L))))
p("uuid version", list(t(uuid(1, 2)), t(uuid(1, 3)), t(uuid(1, 9)), t(uuid(1, 7.5)), t(uuid(1, "7")), t(uuid(1, NA)), t(uuid(1, 8)), t(uuid(1,4,node=raw(6))), t(uuid(1,1,node=1:6)), t(uuid(1,1,node=raw(5))), t(uuid(1,4,random=raw(15))), t(uuid(1,4,random=1:16))))
p("uuid v8 random ff", uuid(1, 8, random=as.raw(rep(255,16)))); p("uuid v4 random 0", uuid(1, 4, random=raw(16)))
p("uuid v1 n=3 random 8*3", uuid(3, 1, random=raw(24)))
p("uuid namespace ignored", uuid(1, 7, namespace="x", name="y"))
